(function(){'use strict';tinymce.PluginManager.requireLangPack('typograf','en,ru');tinymce.PluginManager.add('typograf',function(editor,url){editor.options.register('typograf',{processor:'object',default:{}});const data=Object.assign({locale:['ru','en-US'],htmlEntity:{}},editor.options.get('typograf')||{});let tp=null;let failed=false;let removed=false;editor.on('remove',function(){removed=true});const notify=function(text){if(!removed)editor.notificationManager.open({text:text,type:'error'})};const eachRule=function(value,action){if(Array.isArray(value))value.forEach(action);else if(value)action(value)};const installCss=function(){if(!tp||removed)return;const rules=Array.isArray(data.enableRule)?data.enableRule:[data.enableRule];if(rules.indexOf('ru/optalign/*')<0)return;const doc=editor.getDoc();if(!doc||doc.getElementById('wr-typograf-optalign'))return;const link=doc.createElement('link');link.id='wr-typograf-optalign';link.rel='stylesheet';link.href=url+'/dist/typograf.css';doc.head.appendChild(link)};editor.on('init',installCss);const initialize=function(){if(removed)return;const TypografClass=window.Typograf;if(typeof TypografClass!=='function'){throw new Error('Typograf constructor was not loaded')}if(Array.isArray(data.addRule)){data.addRule.forEach(function(rule){TypografClass.addRule(rule)})}tp=new TypografClass({locale:data.locale,htmlEntity:data.htmlEntity});if(Array.isArray(data.addSafeTag)){data.addSafeTag.forEach(function(pair){tp.addSafeTag(pair[0],pair[1])})}eachRule(data.enableRule,function(rule){tp.enableRule(rule)});eachRule(data.disableRule,function(rule){tp.disableRule(rule)});if(Array.isArray(data.setSetting)){data.setSetting.forEach(function(setting){tp.setSetting(setting[0],setting[1],setting[2])})}if(editor.initialized)installCss()};const loader=new tinymce.dom.ScriptLoader();const dependency=typeof window.Typograf==='function'?Promise.resolve():loader.loadScript(url+'/dist/typograf.all.min.js');dependency.then(initialize).catch(function(error){failed=true;console.error('[typograf]',error);notify('Не удалось загрузить или настроить Типограф. Проверьте консоль и файлы dist.')});const run=function(){if(!tp){notify(failed?'Типограф не загрузился. Проверьте консоль.':'Типограф еще загружается. Повторите действие.');return}try{const result=tp.execute(editor.getContent());editor.undoManager.transact(function(){editor.setContent(result)});editor.setDirty(true);editor.nodeChanged();editor.dispatch('change')}catch(error){console.error('[typograf]',error);notify('Не удалось обработать текст. Исходное содержимое не заменено.')}};editor.ui.registry.addButton('typograf',{icon:'quote',tooltip:'Типограф',onAction:run});editor.ui.registry.addMenuItem('typograf',{icon:'quote',text:'Типограф',onAction:run});return{getMetadata:function(){return{name:'Typograf - TinyMCE 6 adapter',url:'https://github.com/Dominus77/typograf'}}}})}());
